window.__denzingerWorks["dz_025"] = {"id":"dz_025","a":"Denzinger (1819-1883) — 11e éd., Bannwart S.J., 1911","t":"S. INNOCENTIUS I 401—417","u":"https://archive.org/details/enchiridionsymbo01denz","c":[{"t":"S. INNOCENTIUS I 401—417","s":[{"t":"S. INNOCENTIUS I 401—417","p":["reddidit, iam depulso terrore communionem dari abeuntibus placuit, et propter Domini misericordiam quasi viaticum profecturis, et ne Novatiani haeretici negantis veniam asperitatem et duritiam sequi videamur. Tribuetur ergo cum poenitentia extrema communio : ut homines huiusmodi vel in extremis suis permittente Salvatore nostro a perpetuo exitio vindicentur [v. n. 1538].","De canone s. Scripturae et de libris apocryphis *."]},{"t":"eadem epistola ad Exuperium","p":["voce voluisti: JMoysi libri V, id est, Genesis, Exodi, Levitici, Numeri, Deuteronomii et lesu Nave, ludicum I, Regnorum libri IV, simul et Ruth, Prophetarum libri XVI, Salomonis hbri V, Psalterium. Item historiarum, lob Hber I, Tobi Hber I, Esther I, ludith I, IVIachabaeorum II, Esdrae II, ParaHpomenon Hbri II. Item Novi Testamenti : EvangeHorum libri IV, PauH ApostoH epistolae XIV, epistolae loannis III [cf. n. 84 92], epistolae Petri II, epistola ludae, epistola lacobi, Actus Apostolorum, Apocalypsis loannis.","Cetera autem, quae sub nomine Mathiae sive lacobi minoris, vel sub nomine Petri et loannis, quae a quodam Leucio scripta sunt (vel sub nomine Andreae, quae a Nexocharide et Leonida philosophis) vel sub nomine Thomae, et si qua sunt aHa, non solum repudianda, verum etiam noveris esse damnanda.","De baptismo Paulianistarum *."]},{"t":"ep. (17) «Magna me gratulatio» ad Rufum et alios episc","p":["97 Ex canone Nicaeno [n. 56] baptizandos quidem essessi","(63) Paidianistas ad Ecclesiam venientes, non vero Novatianos:","(5) . . . Quod idcirco distinctum esse ipsis duabus hae-","resibus, ratio manifesta declarat, quia Paulianistae","in nomine Patris et Filii et Spiritus Sancti","1 Cst 795 B sq; ML 20, 501 A sq; Msi III 1040 E sq. « Cst 836 BC; Jf 303; ML 20, 533 B; Msi III 1061 E.","Canon. — Bapt. Paulianist. — Confirmatio. — Extrema unctio. 45","minime baptizant, et Novatiani iisdem nominibus tremendis venerandisque baptizant, nec apud istos de unitate potestatis divinae, hoc est Patris et Filii et Spiritus Sancti, quaestio aHquando commota est."]},{"t":"ep. (25) «Si instituta ecclesiastica» ad Decentium Episc","p":["871 (3) De consignandis vero infantibus manifestum est,98 non ab alio quam ab episcopo fieri licere.(60) Nam presbyteri, Hcet secundi sint sacerdotes, pontificatus tamen apicem non habent. Hoc autem pontificium soHs deberi episcopis, ut vei consignent, vel Paracletum Spiritum tradant, non solum consuetudo ecclesiastica demonstrat, verum et illa lectio Actuum Apostolorum, quae asserit Petrum et loannem esse directos, qui iam baptizatis traderent Spiritum Sanctum [cf. Act 8, u-i7]. Nam presbyteris sive extra episcopum, sive praesente episcopo cum baptizant, chrismate baptizatos ungere Hcet; sed quod ab episcopo fuerit consecratum, non tamen frontem ex eodem oleo signare, quod solis debeturepiscopis, cum tradunt Spiritum Paracletum. Verba vero dicere non possum, ne magis prodere videar, quam ad consultationem respondere.","De ministro extremae unctionis^"]},{"t":"eadem epistola ad Decentium","p":["907 (8) Sane quoniam de hoc sicut de caeteris consulereQg voluit dilectio tua, adiecit etiam fiHus meus Coelestinus(6i) diaconus in epistola sua, esse a tua dilectione positum iHud, quod in beati Apostoli lacobi epistola conscriptum est : Si infirmus aliquis in vobis est, vocet presbyteros, et orent super eum, ungentes eum oleo in nomine Domini: et oratio fidei salvabit laborantem, et suscitabit illum Dominus, et si peccatum fecit, remittet ei [lac 5, i4sq]. Quod non est dubium de fideHbus aegrotantibus accipi vel intelHgi debere, qui sancto oleo chrismatis per-","1 Cst 858 A sq; Jf 311 c. Add.; ML 20, 554 B sq; Msi III 1029 B. » Cst 862 B sqq; ML 20, 559 B sq; Msi III 1030 E.","ungi possunt, quod ab episcopo confectum, non solum sacerdotibus, sed et omnibus uti Christianis licet in sua aut in suorum necessitate ungendum. Caeterum illud superfluum esse videmus adiectum, ut de episcopo ambigatur quod presbyteris licere non dubium est. Nam idcirco presbyteris dictum est, quia episcopi occupationibus aliis impediti ad omnes languidos ire non possunt. Caeterum si episcopus aut potest aut dignum ducit aliquem a se visitandum, et benedicere et tangere chrismate sine cunctatione potest, cuius est chrisma conficere. Nam poenitentibus istud infundi non potest, quia genus est sacramenti. Nam quibus r e 1 i q u a sacramenta negantur, quomodo unum genus putatur posse concedi?","De primatu et infallibilitate Romani Pontificis^"]},{"t":"ep. (29) «In requirendis Dei rebus» ad episcopos Africanos,","p":["100 (1) In requirendis Dei rebus . . . antiquae traditionis i826 exempla servantes . . . vestrae reHgionis vigorem . . . ^^'^^ vera ratione firmastis, qui ad nostrum referendum approbastis esse iudicium, scientes, quid Apostolicae Sedi, cum omnes hoc loco positi ipsum sequi desideremus Apostolum, debeatur, a quo ipse episcopatus et tota auctoritas nominis huius emersit. Quem sequentes tam mala damnare novimus quam probare laudanda. Vel id vero, quod patrum instituta sacerdotali officio custodientes non censetis esse calcanda, quod illi non humana, sed divina decrevere sententia, ut quidquid, quamvis de disiunctis remotisque provinciis ageretur, non prius ducerent finiendum, nisi ad huius Sedis notitiam perveniret, ut tota huius auctoritate, iusta quae fuerit pronuntiatio firmaretur, indeque sumerent ceterae ecclesiae (velut de natali suo fonte aquae cunctae procederent et per diversas totius mundi regiones puri latices capitis incorrupti manarent), quid praecipere [deberent], quos abluere, quos veluti caeno inemundabili sordidatos mundis digna corporibus unda vitaret.","1 Cst 888 C sq; Jf 321; ML 20, 582 C sq; Msi III 1071 D. '","Primatus et infallibilitas. — Peccatum orig. et gratia. 47"]}]}]};
